package io.github.diodeme.ji.security.oauth;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertThrows;

import io.github.diodeme.ji.security.secret.SecretValue;
import java.io.Serializable;
import java.net.URI;
import java.time.Instant;
import java.util.Optional;
import org.junit.jupiter.api.Test;

final class OAuthSecurityTypesTest {
    @Test
    void tokenSetIsNonSerializableAndMasked() {
        try (var tokens = new OAuthTokenSet(SecretValue.fromUtf8("synthetic-access".toCharArray()),
                Optional.of(SecretValue.fromUtf8("synthetic-refresh".toCharArray())), "Bearer", Optional.of(Instant.EPOCH))) {
            assertFalse(Serializable.class.isAssignableFrom(OAuthTokenSet.class));
            assertFalse(tokens.toString().contains("synthetic-access"));
            assertFalse(tokens.toString().contains("synthetic-refresh"));
        }
    }

    @Test
    void providerMetadataRejectsInsecureEndpointsAndCallbacks() {
        assertThrows(IllegalArgumentException.class, () -> new OAuthProviderMetadata("provider",
                URI.create("http://provider.example/authorize"), URI.create("https://provider.example/token"),
                Optional.empty(), java.util.Set.of()));
        assertThrows(IllegalArgumentException.class, () -> new OAuthProviderMetadata("provider",
                URI.create("https://provider.example/authorize"), URI.create("https://provider.example/token"),
                Optional.empty(), java.util.Set.of(URI.create("http://client.example/callback"))));
    }
}
